#!/usr/bin/env python3
"""publish_to_hf.py -- publish a snapshot (index + citation registry) to Hugging Face.

Contract rev.4: a snapshot is a **self-contained flat directory** named by its
``snapshot_id``. Everything a consumer needs sits under ``<snapshot_id>/`` on the
dataset repo::

    <snapshot_id>/
      snapshot.json                          <- the manifest (files -> sha256)
      README.md
      index/   <name>.npy | <name>.meta.jsonl | <name>.vec.json
      corpus/  row-aligned-corpus.jsonl
      registry/ documents.jsonl | chunks.jsonl | texts.jsonl

The consumer downloads ``<snapshot_id>/`` and points ``JURICODE_SNAPSHOT_DIR`` at
it. There is no separate ``_manifest.json`` -- snapshot.json is the single
provenance/integrity file (two manifests would drift). ``.vec.pkl`` is never
shipped: it holds the same vectors as the ``.npy`` and unpickling runs arbitrary
code in the reader's process (a verifiability product must not ask that).

Discipline (unchanged, plus one):
    - Token from ``os.environ["HF_TOKEN"]`` only; never an argument, never logged.
    - Run the leak scan over the artefacts before publishing (publishing is
      irreversible).
    - **Confirm the local bytes match snapshot.json BEFORE uploading**: for every
      shipped file, sha256(local) must equal the value snapshot.json records for
      it, and the file set must match exactly. We sell "the distribution is
      byte-verifiable against the manifest"; we apply it to ourselves first.
    - Re-download after publishing and re-check sha256 against snapshot.json.
      Any mismatch is a STOP.
"""

from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
from pathlib import Path

_REPO = Path(__file__).resolve().parents[2]

sys.path.insert(0, str(_REPO / "tools" / "dist"))
from build_snapshot import file_plan_parts, sha256_of  # noqa: E402


def verify_local_against_snapshot(snapshot: dict, plan: list[tuple[Path, str]]) -> dict[str, str]:
    """STOP unless the local files exactly match snapshot.json's ``files`` map.

    Checks three things: the shipped dest set equals ``files`` keys exactly (no
    missing, no extra), every source file exists, and sha256(local) == the
    recorded value. Returns dest -> sha256 for reuse by the post-upload check.
    """
    recorded = snapshot.get("files")
    if not isinstance(recorded, dict):
        raise ValueError("snapshot.json has no 'files' map")
    plan_dests = {dest for _src, dest in plan}
    if plan_dests != set(recorded):
        missing = sorted(set(recorded) - plan_dests)
        extra = sorted(plan_dests - set(recorded))
        raise ValueError(
            f"file set disagrees with snapshot.json (missing from plan: {missing}; "
            f"not in snapshot: {extra})"
        )
    local_sha: dict[str, str] = {}
    for src, dest in plan:
        if not src.exists():
            raise FileNotFoundError(f"shipped file missing locally: {src}")
        got = sha256_of(src)
        if got != recorded[dest]:
            raise ValueError(
                f"{dest}: local sha256 {got} != snapshot.json {recorded[dest]} "
                "(regenerate snapshot.json AFTER the file's final bytes, or the "
                "wrong file is being shipped)"
            )
        local_sha[dest] = got
    return local_sha


def distribution_layout(
    snapshot_id: str, plan: list[tuple[Path, str]], snapshot_json: Path
) -> list[tuple[Path, str]]:
    """(local source, repo path) for every uploaded file, snapshot.json first.

    Repo paths are all under ``<snapshot_id>/`` so the dataset holds a
    self-contained directory. README is added by the caller (generated bytes).
    """
    layout = [(snapshot_json, f"{snapshot_id}/snapshot.json")]
    layout += [(src, f"{snapshot_id}/{dest}") for src, dest in plan]
    return layout


def build_readme(snapshot: dict) -> str:
    """HF README (neutral English), driven entirely by snapshot.json. No accuracy
    numbers (claims ledger)."""
    sid = snapshot["snapshot_id"]
    index = snapshot["index"]
    counts = snapshot["counts"]
    name = index["index_name"]
    model = index["embedding_model"]
    pv = snapshot["pipeline_version"]
    excl = snapshot.get("embed_exclusions", {})
    return f"""---
license: mit
language:
  - ja
tags:
  - legal
  - japanese-law
  - retrieval
  - embeddings
---

# JuriCode-JP snapshot `{sid}`

A self-contained snapshot of structured Japanese statutory law for retrieval, with a
citation registry that lets a consumer verify that a quoted passage is byte-identical
to the source text. Download this directory and point `JURICODE_SNAPSHOT_DIR` at it.

## Layout

| Path | What it is |
|---|---|
| `snapshot.json` | The manifest: `files` maps every path below to its sha256, plus counts and provenance. Verify the directory against it. |
| `index/{name}.npy` | Dense vectors, `float32`, shape `({counts["index_rows"]}, 3072)` |
| `index/{name}.meta.jsonl` | One row per vector, same order: `chunk_id` and section metadata |
| `index/{name}.vec.json` | `{{provider, model}}` sidecar (no pickle -- see below) |
| `corpus/row-aligned-corpus.jsonl` | The {counts["index_rows"]} embedded chunks, row-aligned with the index |
| `registry/documents.jsonl` | One row per document ({counts["documents"]}), with its content hash |
| `registry/chunks.jsonl` | `chunk_id` -> document id ({counts["chunks"]} chunks) |
| `registry/texts.jsonl` | The `get_article` payload: `juri_id` -> exact text ({counts["texts"]} rows), each hashing to its `documents.jsonl` entry |

Embedding model: `{model}`. Pipeline: `{pv}`.

The `.npy` row at position *i* corresponds to the `.meta.jsonl` row at position *i*.

## Why {sum(excl.get(k, 0) for k in ("rollup", "supplproviso_rollup", "empty_text"))} chunks are in the registry but not the index

`registry/chunks.jsonl` has more rows than the index. The difference is intentional and
recorded in `snapshot.json` as `embed_exclusions`: `-rollup` aggregation chunks (their
text is the sum of child chunks that ARE indexed) and empty-text chunks. Nothing
searchable is missing.

## What `hash_basis` means (read this before trusting a hash)

Every document in the registry carries a `hash_basis` field. **The three values do not
carry the same strength of evidence.** Do not treat them as interchangeable.

| `hash_basis` | Meaning |
|---|---|
| `egov-xml-canonical` | The text was checked against the e-Gov source XML. The hash is the one recorded in the per-law source manifest. |
| `egov-xml-derived` | Supplementary provisions (附則). Derived from the same source XML, but there is no per-article manifest anchor for them yet. |
| `juricode-stored-text` | The hash is over the text as stored here. **It is self-reported.** No external source was re-fetched to confirm it. |

This distribution is **not** "all verified". It is verified where it says it is verified.

## No pickle

Only `.npy`, `.jsonl`, `.json` are distributed. The `.vec.pkl` used internally is **not**
published: it holds the same vectors as the `.npy`, and unpickling executes arbitrary
code in the reader's process. A project whose value proposition is verifiability should
not ship a format that asks the consumer to trust it. The portable `{name}.vec.json`
carries the `{{provider, model}}` the retriever needs.

## Licensing

The structuring layer (schema, ids, chunking, this index) is MIT.
The underlying texts are not ours to relicense: statutes come from e-Gov, circulars and
tax guidance from the National Tax Agency, and rulings from the National Tax Tribunal;
each is used under its own terms. See the source repository for the per-source table.

## Comparing snapshots

Do not diff two snapshots with different `pipeline_version` values. A change in the
pipeline changes how text is chunked and hashed, so a row-by-row diff across versions
measures the pipeline, not the law.

## Integrity

`snapshot.json` records the sha256 of every file in this directory. It is the anchor: a
third party can confirm that what they downloaded is what was published, and that it was
not replaced afterwards.

Source: https://github.com/JuriCode-JP/JuriCode-JP
"""


def _load_snapshot(path: Path) -> dict:
    if not path.exists():
        raise FileNotFoundError(f"snapshot.json not found: {path}")
    return json.loads(path.read_text(encoding="utf-8"))


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--repo-id", default="JuriCode-JP/juricode-index")
    ap.add_argument("--snapshot-json", type=Path, default=_REPO / "build" / "snapshot.json")
    ap.add_argument(
        "--index",
        type=Path,
        default=_REPO / "build" / "embeddings" / "v0.2-aug-v9-gemini",
        help="index prefix (extension-less)",
    )
    ap.add_argument("--registry-dir", type=Path, default=_REPO / "build" / "registry")
    ap.add_argument("--corpus-embed", type=Path, default=_REPO / "build" / "corpus-v9-embed.jsonl")
    ap.add_argument("--version-id", required=True, help="commit-message version id")
    ap.add_argument("--create-repo", action="store_true")
    ap.add_argument("--skip-scan", action="store_true", help="skip the leak scan (discouraged)")
    ap.add_argument("--dry-run", action="store_true")
    args = ap.parse_args()

    snapshot = _load_snapshot(args.snapshot_json)
    snapshot_id = snapshot["snapshot_id"]
    plan = file_plan_parts(args.index, args.registry_dir, args.corpus_embed)

    # ---- integrity gate: local bytes must match snapshot.json BEFORE upload ----
    try:
        local_sha = verify_local_against_snapshot(snapshot, plan)
    except (ValueError, FileNotFoundError) as exc:
        print(f"STOP: {exc}", file=sys.stderr)
        return 1

    layout = distribution_layout(snapshot_id, plan, args.snapshot_json)

    # ---- leak scan (publishing is irreversible) --------------------------------
    if not args.skip_scan:
        print("=== leak scan (distribution contents) ===", flush=True)
        rc = subprocess.run(
            [sys.executable, "-X", "utf8", str(_REPO / "tools" / "dist" / "scan_artifacts.py")]
            + [str(src) for src, _ in layout],
            check=False,
        ).returncode
        if rc != 0:
            print("STOP: leak scan failed. Not publishing.", file=sys.stderr)
            return 1

    print("\n=== distribution layout ===")
    total = 0
    for src, repo_path in layout:
        size = src.stat().st_size
        total += size
        print(f"  {repo_path:52s} {size:>14,d} B")
    print(f"  {'TOTAL':52s} {total:>14,d} B")

    if args.dry_run:
        print("\n(dry-run: nothing uploaded)")
        return 0

    token = os.environ.get("HF_TOKEN")
    if not token:
        print("STOP: HF_TOKEN not in the environment", file=sys.stderr)
        return 1

    from huggingface_hub import HfApi, hf_hub_download

    api = HfApi(token=token)
    if args.create_repo:
        api.create_repo(args.repo_id, repo_type="dataset", private=False, exist_ok=True)
        print(f"\nrepo ready: {args.repo_id} (dataset, public)")

    readme = build_readme(snapshot).encode("utf-8")
    api.upload_file(
        path_or_fileobj=readme,
        path_in_repo=f"{snapshot_id}/README.md",
        repo_id=args.repo_id,
        repo_type="dataset",
        commit_message=f"README for {args.version_id}",
    )
    print(f"uploaded {snapshot_id}/README.md")

    for src, repo_path in layout:
        print(f"uploading {repo_path} ({src.stat().st_size / 1e6:.1f} MB) ...", flush=True)
        api.upload_file(
            path_or_fileobj=str(src),
            path_in_repo=repo_path,
            repo_id=args.repo_id,
            repo_type="dataset",
            commit_message=f"add {repo_path} ({args.version_id})",
        )

    # ---- post-upload verification: re-download and re-check sha256 --------------
    # Shipped files are checked against snapshot.json's recorded value (the same
    # authority the consumer will use); snapshot.json itself against its local sha.
    print("\n=== post-upload verification (re-download, re-check sha256) ===")
    snapshot_json_sha = sha256_of(args.snapshot_json)
    bad = []
    for _src, repo_path in layout:
        dest = repo_path[len(snapshot_id) + 1 :]  # strip "<snapshot_id>/"
        want = local_sha[dest] if dest in local_sha else snapshot_json_sha
        got_path = hf_hub_download(
            repo_id=args.repo_id, filename=repo_path, repo_type="dataset", token=token
        )
        got = sha256_of(Path(got_path))
        ok = got == want
        print(f"  {'OK  ' if ok else 'FAIL'} {repo_path:52s} {got}")
        if not ok:
            bad.append(repo_path)
    if bad:
        print(f"\nSTOP: distribution does not match the source: {bad}", file=sys.stderr)
        return 1

    print(f"\ndone -> https://huggingface.co/datasets/{args.repo_id}/tree/main/{snapshot_id}")
    print("every file's sha256 matches snapshot.json (distribution verified byte-for-byte)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
